/**
 * Planner test vectors from the vendored nextdraw 1.7.5, generated by
 * test/oracle/planner_vectors.py into test/fixtures/planner-vectors.json.
 * Regenerate rather than edit.
 */

import { readFileSync } from "node:fs";

export function plannerVectors(): unknown {
  return JSON.parse(
    readFileSync(
      new URL("../fixtures/planner-vectors.json", import.meta.url),
      "utf8"
    )
  );
}
